<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Oidc\GdprConsent\Infrastructure\Service;

use DateTimeImmutable;
use Civi\Lughauth\Shared\Value\Random;
use Civi\Lughauth\Features\Access\User\Domain\UserRef;
use Civi\Lughauth\Features\Access\ConsentPurpose\Domain\ConsentPurposeRef;
use Civi\Lughauth\Features\Access\UserConsentPurposes\Domain\UserConsentPurposes;
use Civi\Lughauth\Features\Access\UserConsentPurposes\Domain\UserConsentPurposesAttributes;
use Civi\Lughauth\Features\Access\UserConsentPurposes\Domain\Gateway\UserConsentPurposesFilter;
use Civi\Lughauth\Features\Access\UserConsentPurposes\Domain\Gateway\UserConsentPurposesWriteGateway;

final class UserConsentPurposeGrant
{
    public function __construct(
        private readonly UserConsentPurposesWriteGateway $write,
    ) {
    }

    /**
     * Stores grant/deny decisions for a set of purposes.
     * Idempotent: existing records are updated; new ones are created.
     *
     * @param array<string,bool> $decisions  purposeUid => granted
     */
    public function grant(UserRef $user, array $decisions, string $ipAddress, string $userAgent): void
    {
        if (!$decisions) {
            return;
        }

        $purposeUids = array_keys($decisions);

        $filter = (new UserConsentPurposesFilter())->withUser($user)->withConsentPurposes($purposeUids);
        $existing = [];
        foreach ($this->write->listForUpdate($filter)->values() as $consent) {
            $existing[$consent->getConsentPurpose()->uid()] = $consent;
        }

        $now = new DateTimeImmutable();

        foreach ($decisions as $purposeUid => $granted) {
            if (isset($existing[$purposeUid])) {
                $updated = $existing[$purposeUid]->update(
                    (new UserConsentPurposesAttributes())
                        ->granted($granted)
                        ->decisionAt($now)
                        ->ipAddress($ipAddress)
                        ->userAgent($userAgent)
                );
                $this->write->update($existing[$purposeUid], $updated);
            } else {
                $newConsent = UserConsentPurposes::create(
                    (new UserConsentPurposesAttributes())
                        ->uid(Random::uuid())
                        ->user($user)
                        ->consentPurpose(new ConsentPurposeRef($purposeUid))
                        ->granted($granted)
                        ->decisionAt($now)
                        ->ipAddress($ipAddress)
                        ->userAgent($userAgent)
                );
                $this->write->create($newConsent);
            }
        }
    }
}
